// Hash routes keep direct links/refresh/back/forward working with the private Worker.
// Inactive pages are detached, not stacked below the active view. Their DOM state is retained.
const pages=new Map();let active=null,initialized=false;
const aliases={overview:'home',assistant:'assistant',priorities:'tasks',allTasks:'tasks',deadlines:'tasks',week:'calendar',announcements:'announcements',courses:'courses',attendance:'attendance',sources:'sources',future:'sources',history:'sources'};
const labels={home:'Çalışma masam',tasks:'Ödevlerim',calendar:'Ders programı',assistant:'Kepler’e sor',announcements:'Duyurular',courses:'Ders klasörlerim',attendance:'Kişisel yoklamam',sources:'Kaynak durumu'};
const descriptions={tasks:'Yaklaşan işler ve kişisel hazırlıkların.',calendar:'Haftanı gör, katılımını dersin içinden işaretle.',assistant:'Kayıtlı okul bilgilerine kısa bir soru sor.',announcements:'Derslerinden aktarılan duyurular.',attendance:'Kendi kayıtların ve kişisel devamsızlık limitlerin.',sources:'Veri kapsamı, kontrol tarihleri ve geçmiş kayıtlar.'};
export function pageForHash(hash){if(hash.startsWith('#ders/'))return 'courses';if(hash.startsWith('#/'))return hash.slice(2).split('/')[0]||'home';return aliases[hash.slice(1)]||(!hash?'home':'notfound');}
export function uiQuery(selector){const found=document.querySelector(selector);if(found)return found;for(const root of pages.values()){if(root.matches(selector))return root;const node=root.querySelector(selector);if(node)return node;}return null;}
export function uiQueryAll(selector){const result=new Set(document.querySelectorAll(selector));for(const root of pages.values()){if(root.matches(selector))result.add(root);root.querySelectorAll(selector).forEach(node=>result.add(node));}return [...result];}
export function routeHref(hash){if(!hash)return '#/home';if(hash.startsWith('#/')||hash.startsWith('#ders/'))return hash;return aliases[hash.slice(1)]?'#/'+aliases[hash.slice(1)]:hash;}
export function initRouter(){
 if(initialized)return;initialized=true;const main=document.querySelector('main'),footer=main.querySelector('footer'),outlet=document.createElement('div');outlet.id='routeOutlet';main.insertBefore(outlet,footer);
 const roots={home:['.command-hero','#progressOverview'],tasks:['#priorities'],calendar:['#week'],assistant:['#assistant'],announcements:['#announcements'],courses:['#courses'],attendance:['#attendance'],sources:['#sources','#statusStrip','#allTasks','#future','#history']};
 for(const [name,selectors] of Object.entries(roots)){const page=document.createElement('div');page.className='route-page';page.dataset.page=name;if(!['home','courses'].includes(name)){const heading=document.createElement('header');heading.className='route-heading';heading.innerHTML=`<p>KEPLER / ${labels[name].toLocaleUpperCase('tr-TR')}</p><h1 tabindex="-1">${labels[name]}</h1><span>${descriptions[name]}</span>`;page.append(heading);}for(const selector of selectors){const node=main.querySelector(selector);if(node)page.append(node);}pages.set(name,page);}
 main.querySelector('.secondary-list')?.remove();
 document.querySelectorAll('.command-rail a,.skip-link').forEach(a=>{if(a.hash)a.setAttribute('href',routeHref(a.hash));});
 const nav=document.querySelector('.command-rail nav');const attendance=document.createElement('a');attendance.href='#/attendance';attendance.innerHTML='<svg class="nav-doodle" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4h14v17H5ZM9 2h6v5H9Zm-1 9 2 2 5-5m-7 9h8"/></svg> Kişisel yoklamam';nav.append(attendance);
 const sources=document.createElement('a');sources.href='#/sources';sources.className='rail-source-link';sources.textContent='Kaynak durumu ↗';document.querySelector('.rail-bottom').prepend(sources);
 function render(focus=false){const name=pageForHash(location.hash),page=pages.get(name);if(active===name&&page&&outlet.firstElementChild===page){window.scrollTo({top:0,left:0,behavior:'instant'});return;}active=name;outlet.replaceChildren();if(page){outlet.append(page);page.querySelectorAll('details.secondary-item').forEach(el=>{if(['sources','announcements','attendance'].includes(el.id))el.open=true});}else{const missing=document.createElement('section');missing.className='route-heading';missing.innerHTML='<h1 tabindex="-1">Sayfa bulunamadı.</h1><a href="#/home">Çalışma masama dön →</a>';outlet.append(missing);}document.body.dataset.page=name;document.querySelector('.command-location').textContent='Kepler / '+(labels[name]||'Sayfa bulunamadı');document.querySelectorAll('.command-rail nav a').forEach(a=>{const selected=pageForHash(a.hash)===name;a.classList.toggle('rail-active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=(labels[name]||'Kepler')+' · Kepler';window.scrollTo({top:0,left:0,behavior:'instant'});if(focus)requestAnimationFrame(()=>{(outlet.querySelector('h1')||outlet.querySelector('h2'))?.focus({preventScroll:true})});}
 document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;const target=routeHref(a.hash);if(target!==a.hash)a.setAttribute('href',target);e.preventDefault();if(location.hash===target)render(true);else location.hash=target;},true);
 window.addEventListener('hashchange',()=>render(true));render(false);
}
